/**
 * Container Card Component
 *
 * Reusable card component for displaying a container in the list view.
 * Shows container type, child count, and leaf/non-leaf status.
 */

import { Book, Books, FolderOpen, Gear, Trash } from '@phosphor-icons/react';
import type React from 'react';
import { useState } from 'react';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import type { Container } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/organisms/card/elevated-shadow.css';
import '@/design-system/tokens/spacing.css';

interface ContainerCardProps {
  container: Container;
  childCount?: { containers: number; stories: number };
  onClick: (container: Container) => void;
  onDelete: (container: Container) => void;
}

// Map container types to icons
const getContainerIcon = (type: string): React.ReactNode => {
  const iconClass = 'icon icon-lg';

  switch (type) {
    case 'novel':
      return <Book className={iconClass} weight="duotone" />;
    case 'series':
      return <Books className={iconClass} weight="duotone" />;
    case 'collection':
      return <FolderOpen className={iconClass} weight="duotone" />;
    default:
      return <FolderOpen className={iconClass} weight="duotone" />;
  }
};

// Format container type for display
const formatContainerType = (type: string): string => {
  return type.charAt(0).toUpperCase() + type.slice(1);
};

// Format timestamp as relative time
const formatTimestamp = (timestamp: string): string => {
  const date = new Date(timestamp);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return 'Just now';
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;

  return date.toLocaleDateString();
};

export function ContainerCard({ container, childCount, onClick, onDelete }: ContainerCardProps) {
  const [isHovered, setIsHovered] = useState(false);
  const navigate = useNavigationStore((state) => state.navigate);

  const handleCardClick = (e: React.MouseEvent) => {
    // Don't trigger card click if clicking action buttons
    if ((e.target as HTMLElement).closest('.container-card-actions')) {
      return;
    }
    onClick(container);
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onDelete(container);
  };

  const handleSettings = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigate({ screen: 'container-settings', containerId: container.id });
  };

  const totalChildren = childCount ? childCount.containers + childCount.stories : 0;

  return (
    <div
      className="option-1 typo-1 icons-1 button-2 card-1"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div
        className="card card-base card-interactive"
        onClick={handleCardClick}
        style={{
          position: 'relative',
          cursor: 'pointer',
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--spacing-3)',
        }}
      >
        {/* Header: Icon and Title */}
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 'var(--spacing-3)' }}>
          <div
            style={{
              flexShrink: 0,
              color: 'var(--color-primary)',
              display: 'flex',
              alignItems: 'center',
            }}
          >
            {getContainerIcon(container.containerType)}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <h3
              style={{
                fontFamily: 'var(--typography-heading-font)',
                fontSize: 'var(--font-size-lg)',
                fontWeight: 'var(--font-weight-semibold)',
                color: 'var(--color-text-primary)',
                margin: 0,
                marginBottom: 'var(--spacing-1)',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}
            >
              {container.title}
            </h3>
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--spacing-2)',
                fontSize: 'var(--font-size-sm)',
                color: 'var(--color-text-secondary)',
              }}
            >
              <span
                style={{
                  padding: '2px 8px',
                  borderRadius: '4px',
                  backgroundColor: 'var(--color-primary-bg)',
                  color: 'var(--color-primary)',
                  fontWeight: 'var(--font-weight-medium)',
                }}
              >
                {formatContainerType(container.containerType)}
              </span>
            </div>
          </div>
        </div>

        {/* Description */}
        {container.description && (
          <p
            style={{
              fontFamily: 'var(--typography-body-font)',
              fontSize: 'var(--font-size-sm)',
              color: 'var(--color-text-secondary)',
              margin: 0,
              lineHeight: 'var(--typography-body-line-height)',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
            }}
          >
            {container.description}
          </p>
        )}

        {/* Footer: Stats and Actions */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            paddingTop: 'var(--spacing-2)',
            borderTop: '1px solid var(--color-border)',
          }}
        >
          {/* Left: Stats */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 'var(--spacing-3)',
              fontSize: 'var(--font-size-xs)',
              color: 'var(--color-text-secondary)',
            }}
          >
            {childCount && (
              <>
                {childCount.containers > 0 && (
                  <span>
                    {childCount.containers}{' '}
                    {childCount.containers === 1 ? 'container' : 'containers'}
                  </span>
                )}
                {childCount.stories > 0 && (
                  <>
                    {childCount.containers > 0 && <span>•</span>}
                    <span>
                      {childCount.stories} {childCount.stories === 1 ? 'story' : 'stories'}
                    </span>
                  </>
                )}
                {totalChildren > 0 && <span>•</span>}
              </>
            )}
            <span>{formatTimestamp(container.updatedAt)}</span>
          </div>

          {/* Right: Hover Actions */}
          {isHovered && (
            <div
              className="container-card-actions"
              style={{
                display: 'flex',
                gap: 'var(--spacing-1)',
              }}
            >
              <button
                className="btn btn-ghost btn-sm"
                onClick={handleSettings}
                title="Container settings"
                style={{ padding: 'var(--spacing-1)' }}
              >
                <Gear className="icon icon-base" weight="duotone" />
              </button>
              <button
                className="btn btn-ghost btn-sm"
                onClick={handleDelete}
                title="Delete container"
                style={{ padding: 'var(--spacing-1)' }}
              >
                <Trash className="icon icon-base" weight="duotone" />
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * Story Card Component
 *
 * Reusable card component for displaying a story in the list view.
 * Uses Elevated Shadow card design from design system.
 */

import {
  BookBookmark,
  Feather,
  FileText,
  FilmStrip,
  Gear,
  Scroll,
  Star,
  Trash,
} from '@phosphor-icons/react';
import type React from 'react';
import { useState } from 'react';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import type { StorySummary, StoryType } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/organisms/card/elevated-shadow.css';
import '@/design-system/tokens/spacing.css';

interface StoryCardProps {
  story: StorySummary;
  onClick: (story: StorySummary) => void;
  onDelete: (story: StorySummary) => void;
  onToggleFavorite: (story: StorySummary) => void;
}

// Map story types to icons (content-only types)
const getStoryIcon = (type: StoryType): React.ReactNode => {
  const iconClass = 'icon icon-lg';

  switch (type) {
    case 'screenplay':
      return <FilmStrip className={iconClass} weight="duotone" />;
    case 'short-story':
      return <FileText className={iconClass} weight="duotone" />;
    case 'poem':
      return <Feather className={iconClass} weight="duotone" />;
    case 'chapter':
      return <BookBookmark className={iconClass} weight="duotone" />;
    case 'scene':
      return <Scroll className={iconClass} weight="duotone" />;
    case 'episode':
      return <FilmStrip className={iconClass} weight="duotone" />;
    case 'outline':
      return <FileText className={iconClass} weight="duotone" />;
    case 'treatment':
      return <FileText className={iconClass} weight="duotone" />;
    default:
      return <FileText className={iconClass} weight="duotone" />;
  }
};

// Format status for display
const formatStatus = (status: string): string => {
  return status
    .split('-')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
};

// Format timestamp as relative time
const formatTimestamp = (timestamp: string): string => {
  const date = new Date(timestamp);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return 'Just now';
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;

  return date.toLocaleDateString();
};

export function StoryCard({ story, onClick, onDelete, onToggleFavorite }: StoryCardProps) {
  const [isHovered, setIsHovered] = useState(false);
  const navigate = useNavigationStore((state) => state.navigate);

  const handleCardClick = (e: React.MouseEvent) => {
    // Don't trigger card click if clicking action buttons
    if ((e.target as HTMLElement).closest('.story-card-actions')) {
      return;
    }
    onClick(story);
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onDelete(story);
  };

  const handleToggleFavorite = (e: React.MouseEvent) => {
    e.stopPropagation();
    onToggleFavorite(story);
  };

  const handleSettings = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigate({ screen: 'story-settings', storyId: story.id });
  };

  return (
    <div
      className="option-1 typo-1 icons-1 button-2 card-1"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div
        className="card card-base card-interactive"
        onClick={handleCardClick}
        style={{
          position: 'relative',
          cursor: 'pointer',
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--spacing-3)',
        }}
      >
        {/* Header: Icon and Title */}
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 'var(--spacing-3)' }}>
          <div
            style={{
              flexShrink: 0,
              color: 'var(--color-primary)',
              display: 'flex',
              alignItems: 'center',
            }}
          >
            {getStoryIcon(story.storyType)}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <h3
              style={{
                fontFamily: 'var(--typography-heading-font)',
                fontSize: 'var(--font-size-lg)',
                fontWeight: 'var(--font-weight-semibold)',
                color: 'var(--color-text-primary)',
                margin: 0,
                marginBottom: 'var(--spacing-1)',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}
            >
              {story.title}
            </h3>
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--spacing-2)',
                fontSize: 'var(--font-size-sm)',
                color: 'var(--color-text-secondary)',
              }}
            >
              <span>{formatStatus(story.storyType)}</span>
            </div>
          </div>
          {story.favorite && (
            <Star
              className="icon icon-base"
              weight="fill"
              style={{
                color: 'var(--color-accent)',
                flexShrink: 0,
              }}
            />
          )}
        </div>

        {/* Description */}
        {story.description && (
          <p
            style={{
              fontFamily: 'var(--typography-body-font)',
              fontSize: 'var(--font-size-sm)',
              color: 'var(--color-text-secondary)',
              margin: 0,
              lineHeight: 'var(--typography-body-line-height)',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
            }}
          >
            {story.description}
          </p>
        )}

        {/* Footer: Stats and Actions */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            paddingTop: 'var(--spacing-2)',
            borderTop: '1px solid var(--color-border)',
          }}
        >
          {/* Left: Stats */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 'var(--spacing-3)',
              fontSize: 'var(--font-size-xs)',
              color: 'var(--color-text-secondary)',
            }}
          >
            <span
              style={{
                padding: '2px 8px',
                borderRadius: '4px',
                backgroundColor:
                  story.status === 'completed'
                    ? 'var(--color-success-bg)'
                    : story.status === 'inprogress'
                      ? 'var(--color-primary-bg)'
                      : 'var(--color-surface)',
                color:
                  story.status === 'completed'
                    ? 'var(--color-success)'
                    : story.status === 'inprogress'
                      ? 'var(--color-primary)'
                      : 'var(--color-text-secondary)',
                fontWeight: 'var(--font-weight-medium)',
              }}
            >
              {formatStatus(story.status)}
            </span>
            <span>•</span>
            <span>{formatTimestamp(story.lastEditedAt)}</span>
          </div>

          {/* Right: Hover Actions */}
          {isHovered && (
            <div
              className="story-card-actions"
              style={{
                display: 'flex',
                gap: 'var(--spacing-1)',
              }}
            >
              <button
                className="btn btn-ghost btn-sm"
                onClick={handleToggleFavorite}
                title={story.favorite ? 'Remove from favorites' : 'Add to favorites'}
                style={{ padding: 'var(--spacing-1)' }}
              >
                <Star
                  className="icon icon-base"
                  weight={story.favorite ? 'fill' : 'duotone'}
                  style={{
                    color: story.favorite ? 'var(--color-accent)' : 'currentColor',
                  }}
                />
              </button>
              <button
                className="btn btn-ghost btn-sm"
                onClick={handleSettings}
                title="Story settings"
                style={{ padding: 'var(--spacing-1)' }}
              >
                <Gear className="icon icon-base" weight="duotone" />
              </button>
              <button
                className="btn btn-ghost btn-sm"
                onClick={handleDelete}
                title="Delete story"
                style={{ padding: 'var(--spacing-1)' }}
              >
                <Trash className="icon icon-base" weight="duotone" />
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * Element Card Component
 *
 * Reusable card component for displaying a universe element in the list view.
 * Uses Elevated Shadow card design from design system.
 */

import {
  Bird,
  Buildings,
  Calendar,
  Car,
  Lightbulb,
  Link,
  MapPin,
  Package,
  PencilSimple,
  Star,
  Trash,
  User,
} from '@phosphor-icons/react';
import type React from 'react';
import { useState } from 'react';
import type { Element, ElementType } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/organisms/card/elevated-shadow.css';
import '@/design-system/tokens/spacing.css';

interface ElementCardProps {
  element: Element;
  relationshipCount?: number;
  onClick: (element: Element) => void;
  onEdit: (element: Element) => void;
  onDelete: (element: Element) => void;
  onToggleFavorite: (element: Element) => void;
}

// Map element types to Phosphor icons
const getElementIcon = (type: ElementType): React.ReactNode => {
  switch (type) {
    case 'character':
      return <User size={24} weight="duotone" />;
    case 'location':
      return <MapPin size={24} weight="duotone" />;
    case 'vehicle':
      return <Car size={24} weight="duotone" />;
    case 'item':
      return <Package size={24} weight="duotone" />;
    case 'organization':
      return <Buildings size={24} weight="duotone" />;
    case 'creature':
      return <Bird size={24} weight="duotone" />;
    case 'event':
      return <Calendar size={24} weight="duotone" />;
    case 'concept':
      return <Lightbulb size={24} weight="duotone" />;
    default:
      return <Package size={24} weight="duotone" />;
  }
};

// Format element type for display
const formatElementType = (type: ElementType, customTypeName?: string | null): string => {
  if (type === 'custom' && customTypeName) {
    return customTypeName;
  }

  return type.charAt(0).toUpperCase() + type.slice(1);
};

export function ElementCard({
  element,
  relationshipCount,
  onClick,
  onEdit,
  onDelete,
  onToggleFavorite,
}: ElementCardProps) {
  const [isHovered, setIsHovered] = useState(false);

  const handleCardClick = (e: React.MouseEvent) => {
    // Don't trigger card click if clicking action buttons
    if ((e.target as HTMLElement).closest('.element-card-actions')) {
      return;
    }
    onClick(element);
  };

  const handleEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    onEdit(element);
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onDelete(element);
  };

  const handleToggleFavorite = (e: React.MouseEvent) => {
    e.stopPropagation();
    onToggleFavorite(element);
  };

  // Calculate relationship count from element data if not provided
  const actualRelationshipCount =
    relationshipCount !== undefined
      ? relationshipCount
      : (element.relationships?.length ?? 0) + (element.relatedStoryIds?.length ?? 0);

  return (
    <div
      className="option-1 typo-1 icons-1 button-2 card-1"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div
        className="card card-base card-interactive"
        onClick={handleCardClick}
        style={{
          position: 'relative',
          cursor: 'pointer',
          display: 'flex',
          flexDirection: 'column',
          gap: 'var(--spacing-3)',
        }}
      >
        {/* Header: Icon and Title */}
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 'var(--spacing-3)' }}>
          <div
            style={{
              flexShrink: 0,
              color: element.color || 'var(--color-primary)',
              display: 'flex',
              alignItems: 'center',
            }}
          >
            {getElementIcon(element.elementType)}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <h3
              style={{
                fontFamily: 'var(--typography-heading-font)',
                fontSize: 'var(--font-size-lg)',
                fontWeight: 'var(--font-weight-semibold)',
                color: 'var(--color-text-primary)',
                margin: 0,
                marginBottom: 'var(--spacing-1)',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}
            >
              {element.name}
            </h3>
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--spacing-2)',
                fontSize: 'var(--font-size-sm)',
                color: 'var(--color-text-secondary)',
              }}
            >
              <span>{formatElementType(element.elementType, element.customTypeName)}</span>
              {actualRelationshipCount > 0 && (
                <>
                  <span>•</span>
                  <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                    <Link
                      className="icon icon-sm"
                      weight="duotone"
                      style={{ width: '14px', height: '14px' }}
                    />
                    {actualRelationshipCount} {actualRelationshipCount === 1 ? 'link' : 'links'}
                  </span>
                </>
              )}
            </div>
          </div>
          {element.favorite && (
            <Star
              className="icon icon-base"
              weight="fill"
              style={{
                color: 'var(--color-accent)',
                flexShrink: 0,
              }}
            />
          )}
        </div>

        {/* Description */}
        {element.description && (
          <p
            style={{
              fontFamily: 'var(--typography-body-font)',
              fontSize: 'var(--font-size-sm)',
              color: 'var(--color-text-secondary)',
              margin: 0,
              lineHeight: 'var(--typography-body-line-height)',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
            }}
          >
            {element.description}
          </p>
        )}

        {/* Footer: Tags and Actions */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            paddingTop: 'var(--spacing-2)',
            borderTop: '1px solid var(--color-border)',
          }}
        >
          {/* Left: Tags */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 'var(--spacing-2)',
              fontSize: 'var(--font-size-xs)',
              color: 'var(--color-text-secondary)',
              flex: 1,
              overflow: 'hidden',
            }}
          >
            {element.tags && element.tags.length > 0 ? (
              <div
                style={{
                  display: 'flex',
                  gap: 'var(--spacing-2)',
                  flexWrap: 'wrap',
                }}
              >
                {element.tags.slice(0, 3).map((tag, index) => (
                  <span
                    key={index}
                    style={{
                      padding: '2px 8px',
                      borderRadius: '4px',
                      backgroundColor: 'var(--color-surface)',
                      color: 'var(--color-text-secondary)',
                      fontWeight: 'var(--font-weight-medium)',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {tag}
                  </span>
                ))}
                {element.tags.length > 3 && (
                  <span
                    style={{
                      padding: '2px 8px',
                      color: 'var(--color-text-secondary)',
                    }}
                  >
                    +{element.tags.length - 3}
                  </span>
                )}
              </div>
            ) : (
              <span style={{ color: 'var(--color-text-tertiary)', fontStyle: 'italic' }}>
                No tags
              </span>
            )}
          </div>

          {/* Right: Hover Actions */}
          {isHovered && (
            <div
              className="element-card-actions"
              style={{
                display: 'flex',
                gap: 'var(--spacing-1)',
              }}
            >
              <button
                className="btn btn-ghost btn-sm"
                onClick={handleToggleFavorite}
                title={element.favorite ? 'Remove from favorites' : 'Add to favorites'}
                style={{ padding: 'var(--spacing-1)' }}
              >
                <Star
                  className="icon icon-base"
                  weight={element.favorite ? 'fill' : 'duotone'}
                  style={{
                    color: element.favorite ? 'var(--color-accent)' : 'currentColor',
                  }}
                />
              </button>
              <button
                className="btn btn-ghost btn-sm"
                onClick={handleEdit}
                title="Edit element"
                style={{ padding: 'var(--spacing-1)' }}
              >
                <PencilSimple className="icon icon-base" weight="duotone" />
              </button>
              <button
                className="btn btn-ghost btn-sm"
                onClick={handleDelete}
                title="Delete element"
                style={{ padding: 'var(--spacing-1)' }}
              >
                <Trash className="icon icon-base" weight="duotone" />
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * ContainerView
 *
 * Displays details of a single container and manages its child containers and stories.
 * Provides navigation to child containers and stories, with reordering capabilities.
 */

import {
  ArrowLeft,
  CaretDown,
  CaretUp,
  CircleNotch,
  FileText,
  FolderOpen,
  Gear,
  Plus,
} from '@phosphor-icons/react';
import { useEffect, useState } from 'react';
import { CreateContainerModal } from '@/features/containers/components/CreateContainerModal';
import { useContainersStore } from '@/features/containers/stores/useContainersStore';
import { PageLayout } from '@/shared/components/PageLayout';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import type { Container, StorySummary } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/spacing.css';

interface ContainerViewProps {
  containerId: string;
}

export function ContainerView({ containerId }: ContainerViewProps) {
  const navigate = useNavigationStore((state) => state.navigate);
  const goBack = useNavigationStore((state) => state.goBack);

  const {
    getContainer,
    loadContainerChildren,
    getContainerChildren,
    reorderChildren,
    error,
    childrenLoading,
  } = useContainersStore();

  const [container, setContainer] = useState<Container | null>(null);
  const [isLoadingContainer, setIsLoadingContainer] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);

  // Load container and children on mount
  useEffect(() => {
    const loadData = async () => {
      setIsLoadingContainer(true);
      try {
        const loadedContainer = await getContainer(containerId);
        setContainer(loadedContainer);

        // Load children
        await loadContainerChildren(containerId);
      } catch (err) {
        console.error('Failed to load container:', err);
      } finally {
        setIsLoadingContainer(false);
      }
    };

    loadData();
  }, [containerId, getContainer, loadContainerChildren]);

  // Get children from store cache
  const children = getContainerChildren(containerId);
  const isChildrenLoading = childrenLoading[containerId] || false;

  const handleTabChange = (tab: 'stories' | 'universe') => {
    if (tab === 'universe') {
      navigate({ screen: 'universe-list' });
    } else {
      navigate({ screen: 'stories-list' });
    }
  };

  const handleContainerClick = (childContainer: Container) => {
    navigate({ screen: 'container-view', containerId: childContainer.id });
  };

  const handleStoryClick = (story: StorySummary) => {
    navigate({ screen: 'story-editor', storyId: story.id });
  };

  const handleMoveContainerUp = async (index: number) => {
    if (!children || index === 0) return;

    const containerIds = [...children.containers.map((c) => c.id)];
    const storyIds = [...children.stories.map((s) => s.id)];

    // Swap with previous
    [containerIds[index], containerIds[index - 1]] = [containerIds[index - 1], containerIds[index]];

    // Optimistic update handled by store, errors automatically rolled back
    await reorderChildren(containerId, containerIds, storyIds).catch(() => {
      // Error is already set in store state and UI automatically reverted
    });
  };

  const handleMoveContainerDown = async (index: number) => {
    if (!children || index === children.containers.length - 1) return;

    const containerIds = [...children.containers.map((c) => c.id)];
    const storyIds = [...children.stories.map((s) => s.id)];

    // Swap with next
    [containerIds[index], containerIds[index + 1]] = [containerIds[index + 1], containerIds[index]];

    // Optimistic update handled by store, errors automatically rolled back
    await reorderChildren(containerId, containerIds, storyIds).catch(() => {
      // Error is already set in store state and UI automatically reverted
    });
  };

  const handleMoveStoryUp = async (index: number) => {
    if (!children || index === 0) return;

    const containerIds = [...children.containers.map((c) => c.id)];
    const storyIds = [...children.stories.map((s) => s.id)];

    // Swap with previous
    [storyIds[index], storyIds[index - 1]] = [storyIds[index - 1], storyIds[index]];

    // Optimistic update handled by store, errors automatically rolled back
    await reorderChildren(containerId, containerIds, storyIds).catch(() => {
      // Error is already set in store state and UI automatically reverted
    });
  };

  const handleMoveStoryDown = async (index: number) => {
    if (!children || index === children.stories.length - 1) return;

    const containerIds = [...children.containers.map((c) => c.id)];
    const storyIds = [...children.stories.map((s) => s.id)];

    // Swap with next
    [storyIds[index], storyIds[index + 1]] = [storyIds[index + 1], storyIds[index]];

    // Optimistic update handled by store, errors automatically rolled back
    await reorderChildren(containerId, containerIds, storyIds).catch(() => {
      // Error is already set in store state and UI automatically reverted
    });
  };

  if (isLoadingContainer) {
    return (
      <PageLayout activeTab="stories" onTabChange={handleTabChange}>
        <div
          className="option-1 typo-1 icons-1"
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            height: '100%',
            gap: 'var(--spacing-3)',
          }}
        >
          <CircleNotch
            className="icon icon-2xl"
            style={{
              color: 'var(--color-primary)',
              animation: 'spin 1s linear infinite',
            }}
          />
          <p
            style={{
              fontFamily: 'var(--typography-body-font)',
              fontSize: 'var(--font-size-base)',
              color: 'var(--color-text-secondary)',
            }}
          >
            Loading container...
          </p>
        </div>
        <style>
          {`
            @keyframes spin {
              from { transform: rotate(0deg); }
              to { transform: rotate(360deg); }
            }
          `}
        </style>
      </PageLayout>
    );
  }

  if (!container) {
    return (
      <PageLayout activeTab="stories" onTabChange={handleTabChange}>
        <div
          className="option-1 typo-1 icons-1"
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            height: '100%',
            gap: 'var(--spacing-4)',
          }}
        >
          <p
            style={{
              fontFamily: 'var(--typography-body-font)',
              fontSize: 'var(--font-size-base)',
              color: 'var(--color-error)',
            }}
          >
            Container not found
          </p>
          <button className="btn btn-primary btn-base" onClick={goBack}>
            Go Back
          </button>
        </div>
      </PageLayout>
    );
  }

  return (
    <PageLayout activeTab="stories" onTabChange={handleTabChange}>
      <div
        className="option-1 typo-1 icons-1 button-2"
        style={{
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
          padding: 'var(--spacing-6)',
        }}
      >
        {/* Header */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 'var(--spacing-4)',
            marginBottom: 'var(--spacing-6)',
          }}
        >
          {/* Back Button */}
          <button
            className="btn btn-ghost btn-sm"
            onClick={goBack}
            title="Back"
            style={{ padding: 'var(--spacing-2)' }}
          >
            <ArrowLeft className="icon icon-base" />
          </button>

          {/* Title and Description */}
          <div style={{ flex: 1 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--spacing-2)' }}>
              <FolderOpen size={24} weight="duotone" style={{ color: 'var(--color-primary)' }} />
              <h1
                style={{
                  fontFamily: 'var(--typography-heading-font)',
                  fontSize: 'var(--typography-h2-size)',
                  fontWeight: 'var(--typography-h2-weight)',
                  color: 'var(--color-text-primary)',
                  margin: 0,
                }}
              >
                {container.title}
              </h1>
            </div>
            {container.description && (
              <p
                style={{
                  fontFamily: 'var(--typography-body-font)',
                  fontSize: 'var(--font-size-base)',
                  color: 'var(--color-text-secondary)',
                  margin: 'var(--spacing-2) 0 0 0',
                }}
              >
                {container.description}
              </p>
            )}
            <p
              style={{
                fontFamily: 'var(--typography-body-font)',
                fontSize: 'var(--font-size-sm)',
                color: 'var(--color-text-secondary)',
                margin: 'var(--spacing-1) 0 0 0',
              }}
            >
              Type: {container.containerType}
            </p>
          </div>

          {/* Action Buttons */}
          <div style={{ display: 'flex', gap: 'var(--spacing-2)' }}>
            <button
              className="btn btn-ghost btn-base"
              onClick={() => navigate({ screen: 'container-settings', containerId })}
              aria-label="Container settings"
              title="Container settings"
            >
              <Gear size={18} weight="duotone" />
            </button>
            <button className="btn btn-primary btn-base" onClick={() => setShowCreateModal(true)}>
              <Plus className="icon icon-base" />
              Add Child
            </button>
          </div>
        </div>

        {/* Error State */}
        {error && (
          <div
            style={{
              padding: 'var(--spacing-4)',
              backgroundColor: 'var(--color-error-subtle)',
              color: 'var(--color-error)',
              borderRadius: '4px',
              marginBottom: 'var(--spacing-6)',
              fontFamily: 'var(--typography-body-font)',
              fontSize: 'var(--font-size-sm)',
            }}
          >
            {error}
          </div>
        )}

        {/* Loading Children */}
        {isChildrenLoading && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              flex: 1,
              gap: 'var(--spacing-3)',
            }}
          >
            <CircleNotch
              className="icon icon-2xl"
              style={{
                color: 'var(--color-primary)',
                animation: 'spin 1s linear infinite',
              }}
            />
            <p
              style={{
                fontFamily: 'var(--typography-body-font)',
                fontSize: 'var(--font-size-base)',
                color: 'var(--color-text-secondary)',
              }}
            >
              Loading children...
            </p>
          </div>
        )}

        {/* Children List */}
        {!isChildrenLoading && children && (
          <div style={{ flex: 1, overflow: 'auto' }}>
            {/* Child Containers Section */}
            {children.containers.length > 0 && (
              <div style={{ marginBottom: 'var(--spacing-6)' }}>
                <h2
                  style={{
                    fontFamily: 'var(--typography-heading-font)',
                    fontSize: 'var(--typography-h3-size)',
                    fontWeight: 'var(--typography-h3-weight)',
                    color: 'var(--color-text-primary)',
                    margin: '0 0 var(--spacing-4) 0',
                  }}
                >
                  Containers ({children.containers.length})
                </h2>
                <div
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 'var(--spacing-3)',
                  }}
                >
                  {children.containers.map((childContainer, index) => (
                    <div
                      key={childContainer.id}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        padding: 'var(--spacing-4)',
                        backgroundColor: 'var(--color-background-secondary)',
                        borderRadius: '4px',
                        gap: 'var(--spacing-3)',
                        cursor: 'pointer',
                        transition: 'background-color 0.2s',
                      }}
                      onClick={() => handleContainerClick(childContainer)}
                      onMouseEnter={(e) => {
                        e.currentTarget.style.backgroundColor = 'var(--color-background-tertiary)';
                      }}
                      onMouseLeave={(e) => {
                        e.currentTarget.style.backgroundColor = 'var(--color-background-secondary)';
                      }}
                    >
                      <FolderOpen
                        size={24}
                        weight="duotone"
                        style={{ color: 'var(--color-primary)' }}
                      />
                      <div style={{ flex: 1 }}>
                        <h3
                          style={{
                            fontFamily: 'var(--typography-heading-font)',
                            fontSize: 'var(--font-size-lg)',
                            fontWeight: 'var(--typography-h4-weight)',
                            color: 'var(--color-text-primary)',
                            margin: 0,
                          }}
                        >
                          {childContainer.title}
                        </h3>
                        {childContainer.description && (
                          <p
                            style={{
                              fontFamily: 'var(--typography-body-font)',
                              fontSize: 'var(--font-size-sm)',
                              color: 'var(--color-text-secondary)',
                              margin: 'var(--spacing-1) 0 0 0',
                            }}
                          >
                            {childContainer.description}
                          </p>
                        )}
                      </div>
                      <div
                        style={{ display: 'flex', gap: 'var(--spacing-1)' }}
                        onClick={(e) => e.stopPropagation()}
                      >
                        <button
                          className="btn btn-ghost btn-sm"
                          onClick={() => handleMoveContainerUp(index)}
                          disabled={index === 0}
                          title="Move up"
                        >
                          <CaretUp size={16} />
                        </button>
                        <button
                          className="btn btn-ghost btn-sm"
                          onClick={() => handleMoveContainerDown(index)}
                          disabled={index === children.containers.length - 1}
                          title="Move down"
                        >
                          <CaretDown size={16} />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Child Stories Section */}
            {children.stories.length > 0 && (
              <div>
                <h2
                  style={{
                    fontFamily: 'var(--typography-heading-font)',
                    fontSize: 'var(--typography-h3-size)',
                    fontWeight: 'var(--typography-h3-weight)',
                    color: 'var(--color-text-primary)',
                    margin: '0 0 var(--spacing-4) 0',
                  }}
                >
                  Stories ({children.stories.length})
                </h2>
                <div
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 'var(--spacing-3)',
                  }}
                >
                  {children.stories.map((story, index) => (
                    <div
                      key={story.id}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        padding: 'var(--spacing-4)',
                        backgroundColor: 'var(--color-background-secondary)',
                        borderRadius: '4px',
                        gap: 'var(--spacing-3)',
                        cursor: 'pointer',
                        transition: 'background-color 0.2s',
                      }}
                      onClick={() => handleStoryClick(story)}
                      onMouseEnter={(e) => {
                        e.currentTarget.style.backgroundColor = 'var(--color-background-tertiary)';
                      }}
                      onMouseLeave={(e) => {
                        e.currentTarget.style.backgroundColor = 'var(--color-background-secondary)';
                      }}
                    >
                      <FileText
                        size={24}
                        weight="duotone"
                        style={{ color: 'var(--color-accent)' }}
                      />
                      <div style={{ flex: 1 }}>
                        <h3
                          style={{
                            fontFamily: 'var(--typography-heading-font)',
                            fontSize: 'var(--font-size-lg)',
                            fontWeight: 'var(--typography-h4-weight)',
                            color: 'var(--color-text-primary)',
                            margin: 0,
                          }}
                        >
                          {story.title}
                        </h3>
                        <p
                          style={{
                            fontFamily: 'var(--typography-body-font)',
                            fontSize: 'var(--font-size-sm)',
                            color: 'var(--color-text-secondary)',
                            margin: 'var(--spacing-1) 0 0 0',
                          }}
                        >
                          {story.wordCount.toLocaleString()} words · {story.status}
                        </p>
                      </div>
                      <div
                        style={{ display: 'flex', gap: 'var(--spacing-1)' }}
                        onClick={(e) => e.stopPropagation()}
                      >
                        <button
                          className="btn btn-ghost btn-sm"
                          onClick={() => handleMoveStoryUp(index)}
                          disabled={index === 0}
                          title="Move up"
                        >
                          <CaretUp size={16} />
                        </button>
                        <button
                          className="btn btn-ghost btn-sm"
                          onClick={() => handleMoveStoryDown(index)}
                          disabled={index === children.stories.length - 1}
                          title="Move down"
                        >
                          <CaretDown size={16} />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Empty State */}
            {children.containers.length === 0 && children.stories.length === 0 && (
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  padding: 'var(--spacing-8)',
                  gap: 'var(--spacing-4)',
                  textAlign: 'center',
                }}
              >
                <FolderOpen
                  size={64}
                  weight="duotone"
                  style={{
                    color: 'var(--color-text-secondary)',
                    opacity: 0.4,
                  }}
                />
                <h2
                  style={{
                    fontFamily: 'var(--typography-heading-font)',
                    fontSize: 'var(--typography-h3-size)',
                    fontWeight: 'var(--typography-h3-weight)',
                    color: 'var(--color-text-primary)',
                    margin: 0,
                  }}
                >
                  No children yet
                </h2>
                <p
                  style={{
                    fontFamily: 'var(--typography-body-font)',
                    fontSize: 'var(--font-size-base)',
                    color: 'var(--color-text-secondary)',
                    maxWidth: '400px',
                  }}
                >
                  Add child containers or stories to organize your content.
                </p>
                <button className="btn btn-primary btn-lg" onClick={() => setShowCreateModal(true)}>
                  <Plus className="icon icon-base" />
                  Add First Child
                </button>
              </div>
            )}
          </div>
        )}
      </div>
      {showCreateModal && container && (
        <CreateContainerModal
          parentContainer={{ id: container.id, title: container.title }}
          onClose={() => {
            setShowCreateModal(false);
            loadContainerChildren(containerId);
          }}
        />
      )}
    </PageLayout>
  );
}

/**
 * ContainerChildrenView
 *
 * Simplified view for listing child containers and stories.
 * Can be used as a standalone component or embedded in other views.
 */

import { CaretDown, CaretUp, CircleNotch, FileText, FolderOpen } from '@phosphor-icons/react';
import type { Container, ContainerChildren, StorySummary } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/spacing.css';

interface ContainerChildrenViewProps {
  children: ContainerChildren | null;
  isLoading: boolean;
  onContainerClick: (container: Container) => void;
  onStoryClick: (story: StorySummary) => void;
  onMoveContainerUp: (index: number) => void;
  onMoveContainerDown: (index: number) => void;
  onMoveStoryUp: (index: number) => void;
  onMoveStoryDown: (index: number) => void;
  emptyMessage?: string;
}

export function ContainerChildrenView({
  children,
  isLoading,
  onContainerClick,
  onStoryClick,
  onMoveContainerUp,
  onMoveContainerDown,
  onMoveStoryUp,
  onMoveStoryDown,
  emptyMessage = 'No children yet',
}: ContainerChildrenViewProps) {
  // Loading State
  if (isLoading) {
    return (
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          padding: 'var(--spacing-8)',
          gap: 'var(--spacing-3)',
        }}
      >
        <CircleNotch
          className="icon icon-2xl"
          style={{
            color: 'var(--color-primary)',
            animation: 'spin 1s linear infinite',
          }}
        />
        <p
          style={{
            fontFamily: 'var(--typography-body-font)',
            fontSize: 'var(--font-size-base)',
            color: 'var(--color-text-secondary)',
          }}
        >
          Loading children...
        </p>
        <style>
          {`
            @keyframes spin {
              from { transform: rotate(0deg); }
              to { transform: rotate(360deg); }
            }
          `}
        </style>
      </div>
    );
  }

  // Empty State
  if (!children || (children.containers.length === 0 && children.stories.length === 0)) {
    return (
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          padding: 'var(--spacing-8)',
          gap: 'var(--spacing-4)',
          textAlign: 'center',
        }}
      >
        <FolderOpen
          size={64}
          weight="duotone"
          style={{
            color: 'var(--color-text-secondary)',
            opacity: 0.4,
          }}
        />
        <p
          style={{
            fontFamily: 'var(--typography-body-font)',
            fontSize: 'var(--font-size-base)',
            color: 'var(--color-text-secondary)',
          }}
        >
          {emptyMessage}
        </p>
      </div>
    );
  }

  return (
    <div style={{ width: '100%' }}>
      {/* Child Containers Section */}
      {children.containers.length > 0 && (
        <div style={{ marginBottom: 'var(--spacing-6)' }}>
          <h2
            style={{
              fontFamily: 'var(--typography-heading-font)',
              fontSize: 'var(--typography-h3-size)',
              fontWeight: 'var(--typography-h3-weight)',
              color: 'var(--color-text-primary)',
              margin: '0 0 var(--spacing-4) 0',
            }}
          >
            Containers ({children.containers.length})
