  event: KeyboardEvent<HTMLDivElement>,
  onActivate: () => void,
) => {
  if (event.target !== event.currentTarget) {
    return;
  }

  if (event.key !== 'Enter' && event.key !== ' ') {
    return;
  }

  event.preventDefault();
  onActivate();
};

